// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/definitions", wrapper.ListDefinitions)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/definitions/{id}/start", wrapper.StartInstance)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/deploy", wrapper.DeployDefinition)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/instances", wrapper.ListInstances)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/instances/{id}", wrapper.GetInstance)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/instances/{id}/complete", wrapper.CompleteInstanceTask)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/instances/{id}/history", wrapper.GetInstanceHistory)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/instances/{id}/incidents", wrapper.ListIncidents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/instances/{id}/incidents/{incidentId}/resolve", wrapper.ResolveIncident)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/instances/{id}/resume", wrapper.ResumeInstance)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/instances/{id}/visualization", wrapper.GetInstanceVisualization)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/instances/{id}/visualization/widget", wrapper.GetInstanceVisualizationWidget)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/process/execute", wrapper.ExecuteProcess)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/smtp-config", wrapper.GetSMTPConfig)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/tasks", wrapper.ListTasks)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/tasks/{id}/claim", wrapper.ClaimTask)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/tasks/{id}/complete", wrapper.CompleteTask)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/users/{username}/groups", wrapper.GetUserGroups)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/webhooks", wrapper.ListWebhooks)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/webhooks", wrapper.CreateWebhook)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/webhooks/{id}", wrapper.DeleteWebhook)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/webhooks/{id}", wrapper.UpdateWebhook)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/webhooks/{id}/deliveries", wrapper.ListWebhookDeliveries)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/webhooks/{id}/test", wrapper.TestWebhook)

	return m
}

