// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// List process definitions
	// (GET /api/definitions)
	ListDefinitions(ctx context.Context, request ListDefinitionsRequestObject) (ListDefinitionsResponseObject, error)
	// Start process instance
	// (POST /api/definitions/{id}/start)
	StartInstance(ctx context.Context, request StartInstanceRequestObject) (StartInstanceResponseObject, error)
	// Deploy process definition
	// (POST /api/deploy)
	DeployDefinition(ctx context.Context, request DeployDefinitionRequestObject) (DeployDefinitionResponseObject, error)
	// List process instances
	// (GET /api/instances)
	ListInstances(ctx context.Context, request ListInstancesRequestObject) (ListInstancesResponseObject, error)
	// Get process instance
	// (GET /api/instances/{id})
	GetInstance(ctx context.Context, request GetInstanceRequestObject) (GetInstanceResponseObject, error)
	// Complete a wait state / task activity in process instance
	// (POST /api/instances/{id}/complete)
	CompleteInstanceTask(ctx context.Context, request CompleteInstanceTaskRequestObject) (CompleteInstanceTaskResponseObject, error)
	// Get process instance execution history
	// (GET /api/instances/{id}/history)
	GetInstanceHistory(ctx context.Context, request GetInstanceHistoryRequestObject) (GetInstanceHistoryResponseObject, error)
	// List incidents for process instance
	// (GET /api/instances/{id}/incidents)
	ListIncidents(ctx context.Context, request ListIncidentsRequestObject) (ListIncidentsResponseObject, error)
	// Resolve process incident
	// (POST /api/instances/{id}/incidents/{incidentId}/resolve)
	ResolveIncident(ctx context.Context, request ResolveIncidentRequestObject) (ResolveIncidentResponseObject, error)
	// Resume process instance
	// (POST /api/instances/{id}/resume)
	ResumeInstance(ctx context.Context, request ResumeInstanceRequestObject) (ResumeInstanceResponseObject, error)
	// Get process instance visualization data
	// (GET /api/instances/{id}/visualization)
	GetInstanceVisualization(ctx context.Context, request GetInstanceVisualizationRequestObject) (GetInstanceVisualizationResponseObject, error)
	// Get process instance visualization widget HTML
	// (GET /api/instances/{id}/visualization/widget)
	GetInstanceVisualizationWidget(ctx context.Context, request GetInstanceVisualizationWidgetRequestObject) (GetInstanceVisualizationWidgetResponseObject, error)
	// Execute process with JIT auto-deploy
	// (POST /api/process/execute)
	ExecuteProcess(ctx context.Context, request ExecuteProcessRequestObject) (ExecuteProcessResponseObject, error)
	// Get SMTP configuration
	// (GET /api/smtp-config)
	GetSMTPConfig(ctx context.Context, request GetSMTPConfigRequestObject) (GetSMTPConfigResponseObject, error)
	// List human/user tasks
	// (GET /api/tasks)
	ListTasks(ctx context.Context, request ListTasksRequestObject) (ListTasksResponseObject, error)
	// Claim human task
	// (POST /api/tasks/{id}/claim)
	ClaimTask(ctx context.Context, request ClaimTaskRequestObject) (ClaimTaskResponseObject, error)
	// Complete human task
	// (POST /api/tasks/{id}/complete)
	CompleteTask(ctx context.Context, request CompleteTaskRequestObject) (CompleteTaskResponseObject, error)
	// Get user groups
	// (GET /api/users/{username}/groups)
	GetUserGroups(ctx context.Context, request GetUserGroupsRequestObject) (GetUserGroupsResponseObject, error)
	// List configured outgoing webhooks
	// (GET /api/webhooks)
	ListWebhooks(ctx context.Context, request ListWebhooksRequestObject) (ListWebhooksResponseObject, error)
	// Create webhook target
	// (POST /api/webhooks)
	CreateWebhook(ctx context.Context, request CreateWebhookRequestObject) (CreateWebhookResponseObject, error)
	// Delete webhook target
	// (DELETE /api/webhooks/{id})
	DeleteWebhook(ctx context.Context, request DeleteWebhookRequestObject) (DeleteWebhookResponseObject, error)
	// Update webhook target
	// (PUT /api/webhooks/{id})
	UpdateWebhook(ctx context.Context, request UpdateWebhookRequestObject) (UpdateWebhookResponseObject, error)
	// List deliveries for webhook
	// (GET /api/webhooks/{id}/deliveries)
	ListWebhookDeliveries(ctx context.Context, request ListWebhookDeliveriesRequestObject) (ListWebhookDeliveriesResponseObject, error)
	// Test webhook target
	// (POST /api/webhooks/{id}/test)
	TestWebhook(ctx context.Context, request TestWebhookRequestObject) (TestWebhookResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

